#!/bin/sh
# Downloads the pinned third-party decoder sources into this directory,
# keeping only what the build needs. Re-run to refresh; needs curl and tar.
set -eu
cd "$(dirname "$0")"

MINIAUDIO=0.11.22
OGG=1.3.5
OPUS=1.5.2
OPUSFILE=0.12
XMP=4.6.0
FAAD=2.11.1
MINIMP4=2a3014a7753cfcba4442adeb469431967238fe6a

# fetch_tree <dir> <tarball url> <paths to keep...>
fetch_tree() {
    dir=$1; url=$2; shift 2
    echo "fetching $dir"
    rm -rf "$dir" "$dir.tmp"
    mkdir "$dir.tmp" "$dir"
    curl -fsSL "$url" | tar -xz -C "$dir.tmp" --strip-components=1
    for path in "$@"; do
        if [ -e "$dir.tmp/$path" ]; then
            mkdir -p "$dir/$(dirname "$path")"
            mv "$dir.tmp/$path" "$dir/$path"
        fi
    done
    rm -rf "$dir.tmp"
}

curl -fsSL -o miniaudio.h "https://raw.githubusercontent.com/mackron/miniaudio/$MINIAUDIO/miniaudio.h"
curl -fsSL -o stb_vorbis.c "https://raw.githubusercontent.com/mackron/miniaudio/$MINIAUDIO/extras/stb_vorbis.c"
curl -fsSL -o minimp4.h "https://raw.githubusercontent.com/lieff/minimp4/$MINIMP4/minimp4.h"

# minimp4 is header-only; this gives it a translation unit of its own.
printf '#define MINIMP4_IMPLEMENTATION\n#include "minimp4.h"\n' > minimp4.c

fetch_tree ogg "https://github.com/xiph/ogg/archive/refs/tags/v$OGG.tar.gz" include src COPYING
# Normally generated by configure.
cat > ogg/include/ogg/config_types.h <<'EOF'
#ifndef __CONFIG_TYPES_H__
#define __CONFIG_TYPES_H__
#include <stdint.h>
typedef int16_t ogg_int16_t;
typedef uint16_t ogg_uint16_t;
typedef int32_t ogg_int32_t;
typedef uint32_t ogg_uint32_t;
typedef int64_t ogg_int64_t;
typedef uint64_t ogg_uint64_t;
#endif
EOF

fetch_tree opus "https://github.com/xiph/opus/archive/refs/tags/v$OPUS.tar.gz" \
    include celt silk src celt_sources.mk silk_sources.mk opus_sources.mk COPYING
fetch_tree opusfile "https://github.com/xiph/opusfile/archive/refs/tags/v$OPUSFILE.tar.gz" include src COPYING
fetch_tree libxmp-lite "https://github.com/libxmp/libxmp/releases/download/libxmp-$XMP/libxmp-lite-$XMP.tar.gz" \
    include src README
fetch_tree faad2 "https://github.com/knik0/faad2/archive/refs/tags/$FAAD.tar.gz" include libfaad COPYING
# We link libfaad statically; without this the Windows executable would export its API.
sed -i 's/#define NEAACDECAPI __declspec(dllexport)/#define NEAACDECAPI/' faad2/include/neaacdec.h

# Font sources for tools/genfont.py (see fonts/SOURCE.md).
echo "fetching fonts"
mkdir -p fonts
curl -fsSL https://www.cl.cam.ac.uk/~mgk25/download/ucs-fonts.tar.gz |
    tar -xz -C fonts 5x7.bdf 6x10.bdf 7x13.bdf 9x15.bdf 10x20.bdf README

echo "done"
